TWComponent.script:
function stringToList(string) {
	var stringList = new tw.object.listOf.String();
	stringList[0] = string;
	return stringList;
}

function floatToStringList(float) {
	var stringList = new tw.object.listOf.String();
	stringList[0] = "" + float;
	return stringList;
}

function booleanToStringList(boolean) {
	var stringList = new tw.object.listOf.String();
	if (boolean)
		stringList[0] = "نعم"
	else
		stringList[0] = "لا"
	return stringList;
}

function formatDate(date) {
	if(!!date){
	date.setHours(date.getHours() + 2);
	var d = new Date(date),
		day = '' + (d.getDate()),
		month = '' + (d.getMonth() + 1),
		year = d.getFullYear();

	if (month.length < 2)
		month = '0' + month;
	if (day.length < 2)
		day = '0' + day;

	return [day, month, year].join('/');
	}
	else
	return null;
}

function minDate(dates){

	var minDt = dates[0];
	var minDtObj = new Date(dates[0]);
	dates.forEach(function(dt,index){
		var currenDtObj = new Date(dt);
		if(currenDtObj < minDtObj){
			minDt = dt;
			minDtObj = new Date(dt);
		}
	
	});
	
	return minDt;
	
	
}

tw.local.request = new tw.object.DocumentGenerationRequest();
tw.local.request.templates = new tw.object.listOf.RequestTemplatePojo();
//tw.local.request.templates[0] = new tw.object.RequestTemplatePojo();

tw.local.request.appName = "ODC create/Amend";
tw.local.request.purposeCode = new tw.object.listOf.String();
tw.local.request.purposeCode[0] = "PUR1";

tw.local.request.programCode = "PROG1";
//"PROG1";

tw.local.request.secure = true;

tw.local.paramsValues = new tw.object.Map();


//---------------------------------------------------
var ecmInfo = new tw.object.EcmDocumentInformation();
ecmInfo.docClassName = "ODCRemittanceLetter";
ecmInfo.docProperties = "";
ecmInfo.folderId = tw.local.docGenTempFolder.path;

if (tw.local.generationStatus == "Generate") {
	var title = "";
}
else {
	if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value == "other") {
		var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle;
	}
	else {
		var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value;
	}
}
//var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value + tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle;
tw.local.paramsValues.put("Title001", stringToList(title));
var date = new tw.object.Date();
tw.local.paramsValues.put("Date001", stringToList(formatDate(date)));
var swiftCode = "NBEGEGCX" + tw.local.odcRequest.FinancialDetailsFO.executionHub.value;

tw.local.paramsValues.put("Swift001", stringToList(swiftCode));
tw.local.paramsValues.put("Int001", stringToList(tw.local.odcRequest.ImporterDetails.bank));
tw.local.paramsValues.put("Int002", stringToList(tw.local.odcRequest.ImporterDetails.bankAddress));
tw.local.paramsValues.put("Int003", stringToList(tw.local.odcRequest.ImporterDetails.bankPhoneNo));
tw.local.paramsValues.put("Int004", stringToList(tw.local.odcRequest.ImporterDetails.BICCode));
tw.local.paramsValues.put("Int005", stringToList(tw.local.odcRequest.GeneratedDocumentInfo.customerName));
tw.local.paramsValues.put("Int006", stringToList(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress));
tw.local.paramsValues.put("Int007", stringToList(tw.local.odcRequest.ImporterDetails.importerName));
tw.local.paramsValues.put("Int008", stringToList(tw.local.odcRequest.ImporterDetails.importerAddress));
tw.local.paramsValues.put("Int009", stringToList(tw.local.odcRequest.ImporterDetails.importerPhoneNo));
var rebate = 0;
if(!!tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt && tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt > 0 )
	rebate =  tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt;
tw.local.paramsValues.put("Int010", floatToStringList(tw.local.odcRequest.FinancialDetailsFO.collectableAmount - rebate ));
if(tw.local.odcRequest.FinancialDetailsFO.ourCharges != 0 && tw.local.odcRequest.FinancialDetailsFO.ourCharges != null){
    tw.local.paramsValues.put("Int011", floatToStringList(tw.local.odcRequest.FinancialDetailsFO.ourCharges));
    tw.local.paramsValues.put("Int020", stringToList("Our Charges:"));
    var claimedAmount = tw.local.odcRequest.FinancialDetailsFO.collectableAmount + tw.local.odcRequest.FinancialDetailsFO.ourCharges;
    tw.local.paramsValues.put("Int012", floatToStringList(claimedAmount));
    tw.local.paramsValues.put("Int021", stringToList("Claimed Amount:"));
}    
tw.local.paramsValues.put("Int013", stringToList(tw.local.odcRequest.FinancialDetailsBR.currency.name));

if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "001") {
	tw.local.paramsValues.put("Int014", stringToList("SIGHT"));
}
else if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "005"){
	tw.local.paramsValues.put("Int014", stringToList("Free of Payment"));
}
else if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "002" || tw.local.odcRequest.BasicDetails.paymentTerms.name == "003" ){
	
	if(!!tw.local.odcRequest.ContractCreation.maturityDate){
		tw.local.paramsValues.put("Int014", stringToList(formatDate(tw.local.odcRequest.ContractCreation.maturityDate)));
	}
	
}
else {
	if(!!tw.local.odcRequest.FinancialDetailsFO.multiTenorDates){
		var tenorDates = [];
		for(var i =0; i<tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.listLength;i++)
			tenorDates[i] = tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate;
		tw.local.paramsValues.put("Int014", stringToList(formatDate(minDate(tenorDates))));
	}
	
}
var refNo = tw.local.odcRequest.BasicDetails.flexCubeContractNo;

if(!!tw.local.odcRequest.BasicDetails.flexCubeContractNo2)
	refNo +=" - " + tw.local.odcRequest.BasicDetails.flexCubeContractNo2;
	
tw.local.paramsValues.put("Int015", stringToList(refNo));

var deliveryTerms = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.listLength; i++) {
	deliveryTerms[i] = tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms[i].name;
}
if (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.listLength; i++) {
		deliveryTerms[deliveryTerms.length] = tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i];
	}
}

tw.local.paramsValues.put("Int016", deliveryTerms);

var paymentInstructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.listLength; i++) {
	paymentInstructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions[i].name;
}
var length = paymentInstructions.length;
if (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.listLength; i++) {
		paymentInstructions[paymentInstructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i];
	}
}

tw.local.paramsValues.put("Int017", paymentInstructions);

var instructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.Instructions.listLength; i++) {
	instructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.Instructions[i].name;
}
if (tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.listLength; i++) {
		instructions[instructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i];
	}
}
tw.local.paramsValues.put("Int018", instructions);

var specialInstructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.listLength; i++) {
	specialInstructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions[i].name;
}
if (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.listLength; i++) {
		specialInstructions[specialInstructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i];
	}
}

tw.local.paramsValues.put("Int019", specialInstructions);

////////////////////////////////////////////////////////////////////////////////
var documentNames = new tw.object.listOf.String();
var noOfCopies = new tw.object.listOf.String();
var noOfOriginals = new tw.object.listOf.String();
var docsCount =0;
for (var i = 0; i < tw.local.odcRequest.attachmentDetails.attachment.listLength; i++) {
	if (tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals > 0|| tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies >0) {
		if (tw.local.odcRequest.attachmentDetails.attachment[i].name == "" || tw.local.odcRequest.attachmentDetails.attachment[i].name == null) {
			documentNames[docsCount] = "";
		}
		else {
			documentNames[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].description;
		}
		//if (tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals == "" || tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals == null) {
		//	noOfOriginals[docsCount] = "";
		//}
		//else {
			noOfOriginals[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals + "";
		//}
		//if (tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies == "" || tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies == null) {
		//	noOfCopies[docsCount] = "";
		//}
		//else {
			noOfCopies[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies + "";
		//}
		docsCount++;

	}
//	else{
//		continue;
//	}
}
if(docsCount>0){
	tw.local.paramsValues.put("intr001", documentNames);
	tw.local.paramsValues.put("intr002", noOfOriginals);
	tw.local.paramsValues.put("intr003", noOfCopies);
	tw.local.paramsValues.put("Int023",stringToList("Document Name"));
	tw.local.paramsValues.put("Int024",stringToList("Originals"));
	tw.local.paramsValues.put("Int025",stringToList("Copies"));
	tw.local.paramsValues.put("Int022", stringToList("We enclose herewith the documents mentioned below, under documentary collection"));
}


//tw.local.paramsValues.put("intr001",specialInstructions);
//tw.local.paramsValues.put("intr002",specialInstructions);
//tw.local.paramsValues.put("intr003",specialInstructions);

tw.local.request.paramsValues = tw.local.paramsValues;
//--------------------------Generate Docs-------------------
var template = new tw.object.RequestTemplatePojo();
template.secure = true;
template.ecmDocInfo = ecmInfo;
template.templateCode = "ODCRemittanceLetter";
template.generatedDocName = "remittance Letter";
tw.local.request.templates.insertIntoList(tw.local.request.templates.listLength, template);

processPrePosts.script:
tw.local.regenerate = false;
for (var i =0; i<tw.local.documents.listLength;i++){

	if(tw.local.documents[i].objectTypeId == "ODCRemittanceLetter"){
		tw.local.regenerate = true;
		tw.local.oldDoc = tw.local.documents[i];
		break;
	}	
}

